<script setup>
import { computed, reactive, ref, watchEffect } from 'vue'; import * as _ from 'lodash';
import { BookOpen, Boxes, CircleDot, FileText, GitBranch, MessageSquare, Search, X } from 'lucide-vue-next';
import { useMainStore } from '@/stores/store'; import { useLabels } from '@/composables/useLabels'; import '@/assets/detail-pages.css';
const store=useMainStore(); const {t}=useLabels(); const entity=computed(()=>store.getEntityInfo.entity); const activeTab=ref('attributes'); const activeType=ref('Domain'); const inverse={Domain:'Range',Range:'Domain'};
const filters=reactive({search:'',code:'',name:'',opposite:''}); const grouped=computed(()=>_.groupBy(entity.value.relations,'type')); const types=computed(()=>Object.keys(grouped.value));
watchEffect(()=>{if(types.value.length&&!types.value.includes(activeType.value))activeType.value=types.value[0]});
const relations=computed(()=>Object.entries(_.groupBy(grouped.value[activeType.value]||[],'Relation ID')).map(([id,rows])=>({id,name:rows[0]?.Name||'',opposites:_.uniqBy(rows.map(r=>r[inverse[activeType.value]]).filter(Boolean),'code')})).filter(x=>{const oppositeText=x.opposites.map(o=>`${o.code} ${o.name}`).join(' ').toLowerCase();const allText=`${x.id} ${x.name} ${oppositeText}`.toLowerCase();return allText.includes(filters.search.toLowerCase())&&`${x.id}`.toLowerCase().includes(filters.code.toLowerCase())&&x.name.toLowerCase().includes(filters.name.toLowerCase())&&oppositeText.includes(filters.opposite.toLowerCase())}));
const parts=(v)=>String(v||'').split(/\|\||\r?\n/).map(x=>x.trim()).filter(Boolean);
</script>
<template><article class="detail-page"><nav class="detail-breadcrumb"><button @click="$router.push('/entities')">{{ t('nav.entities') }}</button><template v-for="x in entity.ancestors" :key="x.code"><span>/</span><button @click="store.selectEntity(x.code)">{{ x.code }}</button></template><span>/</span><span>{{ entity.code }}</span></nav><header class="detail-hero"><div class="detail-title-row"><span class="detail-code">{{ entity.code }}</span><h1>{{ entity.name }}</h1></div><p v-if="parts(entity.definition)[0]" class="detail-summary">{{ parts(entity.definition)[0] }}</p></header>
<div class="detail-grid"><div class="detail-stack"><section class="detail-panel"><div class="detail-section"><h2 class="detail-heading"><BookOpen :size="21"/>{{ t('common.definition') }}</h2><p v-for="x in parts(entity.definition)" :key="x">{{ x }}</p></div><div class="detail-section"><h2 class="detail-heading"><CircleDot :size="21"/>{{ t('common.scopeNotes') }}</h2><p v-for="x in parts(entity.scopenotes)" :key="x">{{ x }}</p></div><div class="detail-section example-box"><h2 class="detail-heading"><FileText :size="21"/>{{ t('common.examples') }}</h2><p v-for="x in parts(entity.examples)" :key="x">{{ x }}</p></div><div v-if="parts(entity.comments).length" class="detail-section"><h2 class="detail-heading"><MessageSquare :size="21"/>{{ t('common.comments') }}</h2><p v-for="x in parts(entity.comments)" :key="x">{{ x }}</p></div></section></div>
<aside class="detail-panel detail-side"><h2 class="side-title"><GitBranch :size="20"/>{{ t('entityCard.inModel') }}</h2><div class="side-body"><h3>{{ t('entityCard.ancestors') }}</h3><ul class="hier-list"><li v-for="x in entity.ancestors" :key="x.code"><button @click="store.selectEntity(x.code)">{{ x.code }} {{ x.name }}</button></li></ul><hr><h3>{{ t('entityCard.descendants') }}</h3><ul class="hier-list"><li v-for="x in entity.descendants" :key="x.code"><button @click="store.selectEntity(x.code)">{{ x.code }} {{ x.name }}</button></li></ul></div></aside></div>
<section class="workspace"><div class="tabs"><button :class="{active:activeTab==='attributes'}" @click="activeTab='attributes'"><Boxes :size="17"/>{{ t('entityCard.attributes') }}</button><button :class="{active:activeTab==='relations'}" @click="activeTab='relations'"><GitBranch :size="17"/>{{ t('entityCard.relations') }}</button></div>
<div v-if="activeTab==='attributes'" class="attribute-groups"><section v-for="group in entity.attributes" :key="group.code"><button class="group-title" @click="store.selectEntity(group.code)">{{ group.code }} {{ group.name }} <span>{{ group.attributes.length }}</span></button><ul class="detail-chips"><li v-for="x in group.attributes" :key="x.code"><button class="detail-chip" @click="store.selectAttribute(x.code)">{{ x.code }} {{ x.name }}</button></li></ul></section></div>
<div v-else><div class="relation-toolbar"><div class="relation-search"><Search :size="17"/><input v-model="filters.search" type="search" :placeholder="t('entityCard.searchRelations')"><button v-if="filters.search" :aria-label="t('common.close')" @click="filters.search=''"> <X :size="15"/></button></div><div class="toolbar-end"><div class="type-toggle"><button v-for="type in types" :key="type" :class="{active:activeType===type}" @click="activeType=type">{{ t('entityCard.asType',{type}) }}</button></div><span>{{ relations.length }} {{ t('nav.relations').toLowerCase() }}</span></div></div><div class="relation-table-wrap"><table class="table relation-table"><thead><tr><th>{{ t('common.code') }}</th><th>{{ t('common.name') }}</th><th>{{ inverse[activeType] }}</th></tr><tr><th><Filter v-model="filters.code" :label="t('common.searchCode')"/></th><th><Filter v-model="filters.name" :label="t('common.searchName')"/></th><th><Filter v-model="filters.opposite" :label="t('entityCard.searchType',{type:inverse[activeType]})"/></th></tr></thead><tbody><tr v-for="x in relations" :key="x.id"><td><button class="code-button" @click="store.selectRelation(x.id)">{{ x.id }}</button></td><td>{{ x.name }}</td><td><span v-for="o in x.opposites" :key="o.code" class="detail-chip" @click="store.selectEntity(o.code)">{{ o.code }} {{ o.name }}</span></td></tr></tbody></table><p v-if="!relations.length" class="empty-copy table-empty">{{ t('common.noResults') }}</p></div></div></section></article></template>
<script>const Filter={components:{Search,X},props:{modelValue:String,label:String},emits:['update:modelValue'],template:`<label class="filter"><Search :size="14"/><input :value="modelValue" :placeholder="label" @input="$emit('update:modelValue',$event.target.value)"><button @click.prevent="$emit('update:modelValue','')"><X :size="14"/></button></label>`};export default{components:{Filter}}</script>
<style scoped>.side-body h3{color:#173e6d;font:700 1rem Georgia,serif}.side-body hr{border-color:#cbdff4}.hier-list{margin:0;padding-left:1rem;border-left:2px solid #bad4f1;list-style:none}.hier-list li{position:relative;margin:.4rem 0}.hier-list li:before{content:'';position:absolute;left:-1rem;top:.8rem;width:.75rem;border-top:2px solid #bad4f1}.hier-list button{border:1px solid #c9def5;border-radius:8px;padding:.4rem .55rem;color:#24527f;background:#f7fbff;text-align:left}.workspace{margin-top:1.2rem;border:1px solid var(--line);border-radius:17px;background:#fff;box-shadow:0 10px 30px rgba(22,65,120,.07)}.tabs{display:flex;border-bottom:1px solid var(--line)}.tabs button{display:flex;align-items:center;gap:.4rem;border:0;border-right:1px solid var(--line);padding:.75rem 1.2rem;color:#506780;background:#f7fbff;font-weight:750}.tabs button.active{color:#fff;background:var(--blue)}.attribute-groups{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;padding:1rem}.attribute-groups section{padding:.85rem;border:1px solid #dbe8f7;border-radius:12px;background:#fbfdff}.group-title{width:100%;margin-bottom:.65rem;border:0;color:#123f75;background:none;text-align:left;font-weight:750}.group-title span{float:right;border-radius:999px;padding:.1rem .45rem;background:#e5f1ff}.relation-toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.8rem 1rem;border-bottom:1px solid var(--line);background:#f8fbff}.relation-search{display:flex;align-items:center;gap:.45rem;min-width:min(360px,100%);padding:.5rem .65rem;border:1px solid #bcd5ef;border-radius:9px;color:#66809d;background:#fff}.relation-search input{min-width:0;width:100%;border:0;outline:0;color:#284866;background:transparent}.relation-search button{display:grid;place-items:center;border:0;padding:0;color:#71849b;background:none}.toolbar-end{display:flex;align-items:center;gap:.8rem}.type-toggle{display:flex}.type-toggle button{border:1px solid #b9d5f3;padding:.35rem .65rem;color:var(--blue);background:#fff}.type-toggle button:first-child{border-radius:8px 0 0 8px}.type-toggle button:last-child{border-radius:0 8px 8px 0}.type-toggle button.active{color:#fff;background:var(--blue)}.relation-table-wrap{overflow:auto;max-height:430px}.relation-table{margin:0}.relation-table th,.relation-table td{padding:.65rem;border-color:#e1ebf7}.relation-table thead th{background:#f7fbff}.filter{display:flex;align-items:center;gap:.3rem;min-width:150px;border:1px solid #cddff1;border-radius:7px;padding:.3rem .4rem;background:#fff}.filter input{min-width:0;width:100%;border:0;outline:0}.filter button{border:0;padding:0;color:#71849b;background:none}.code-button{border:0;border-radius:7px;padding:.24rem .45rem;color:var(--blue);background:#eaf3ff;font-weight:800}.table-empty{padding:2rem;text-align:center}@media(max-width:850px){.relation-toolbar{align-items:stretch;flex-direction:column}.toolbar-end{justify-content:space-between}}@media(max-width:700px){.attribute-groups{grid-template-columns:1fr}.toolbar-end{align-items:flex-start;flex-direction:column}}</style>
